class Thermostat {
  target = 20;
  history = [this.target];

  constructor(target) {
    if (target !== undefined) {
      this.target = target;
    }

    this.history.push(this.target);
  }
}

const hall = new Thermostat();
const attic = new Thermostat(15);

console.log(hall.history.join(","));
console.log(attic.history.join(","));
console.log(hall.history === attic.history);
console.log(Object.keys(attic).join(","));
